import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Stamina and recovery","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/stamina-and-reactive-combat.md","filePath":"en/guide/combat/stamina-and-reactive-combat.md"}'),n={name:"en/guide/combat/stamina-and-reactive-combat.md"};function i(o,t,s,l,c,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="stamina-and-reactive-combat" tabindex="-1">Stamina and recovery <a class="header-anchor" href="#stamina-and-reactive-combat" aria-label="Permalink to &quot;Stamina and recovery&quot;">​</a></h1><p><strong>Status:</strong> Experimental resource/timing profile · Not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Stamina makes attack, defense and repeated pressure compete.</li><li>The Experimental pool is 100; it does not settle the future Max Stamina formula.</li><li>All action phases must finish; rushed play costs more and rejected inputs grant no attack.</li></ul><p>Stamina makes attack, defense and repeated pressure compete. Low DEX should not turn basic play into slow motion.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Test rule</th><th>Value / meaning</th></tr></thead><tbody><tr><td>Pool</td><td>100 stamina</td></tr><tr><td>Recovery of stamina</td><td>6/second after 1000 ms without a paid action; none during action phases</td></tr><tr><td>Wind-up</td><td>Preparation before contact</td></tr><tr><td>Active window</td><td>Opportunity to contact, not repeated free hits</td></tr><tr><td>Recovery</td><td>Must finish before the next action, including defense</td></tr><tr><td>Rejected input</td><td>No attack or stamina charge</td></tr></tbody></table><h2 id="repeat-pressure" tabindex="-1">Repeat pressure <a class="header-anchor" href="#repeat-pressure" aria-label="Permalink to &quot;Repeat pressure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Band</th><th>Cost multiplier</th><th>Recovery multiplier</th><th>Accuracy</th></tr></thead><tbody><tr><td>Normal</td><td>×1.00</td><td>×1.00</td><td>No penalty</td></tr><tr><td>Slightly rushed</td><td>×1.10</td><td>×1.05</td><td>−2 pp</td></tr><tr><td>Rushed</td><td>×1.25</td><td>×1.15</td><td>−5 pp</td></tr><tr><td>Spam</td><td>×1.50</td><td>×1.25</td><td>−10 pp</td></tr></tbody></table><p>Modern&#39;s bands compare accepted starts with reference rhythm; unavailable inputs do not bypass phases. Flow and Familiarity factors also apply within explicit bounds. Legacy shares base costs with bounded automatic cadence.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A Heavy Blow costs 28 before modifiers. Missing still spends the action and its recovery; stamina pressure gives the opponent a reason to bait it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/en/guide/characters/stats.html">Stats</a> · <a href="/Syrolands-Public/en/game-design/combat/stamina-and-reactive-combat.html">Full stamina design</a> · <a href="/Syrolands-Public/en/game-design/combat/numeric-prototype.html">Exact test calculations</a></p><p><span id="timing-without-broken-early-characters"></span><span id="manual-attacks-are-a-proposal"></span></p>',15)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
